// #b98032 (6a993d694473aff41cb98032) — статус simulation_started называется «בתהליך» везде: фильтр «סטטוס» в /candidates,
// колонка «ביצוע» списка и лента «פעילות אחרונה» на дашборде; «הסימולציה החלה» нигде (решение пользователя 14.10, Figma 678:652).
// Кейсы CAND-013, DASH-003. Строка/событие со статусом simulation_started ПОДМЕНЯЮТСЯ в ответе list_candidates /
// get_business_dashboard (в базе ничего не создаётся и не меняется) → @prod-safe.
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '@playwright/test';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#b98032 · #6a993d694473aff41cb98032';
const LABEL = 'בתהליך';
const OLD_LABEL = 'הסימולציה החלה';
const FAKE_NAME = 'QA-AUTO-b98032 בתהליך';

type Row = Record<string, unknown> & { full_name: string; invite: Record<string, unknown> | null };

/** Подмена: первая строка list_candidates с приглашением становится «simulation_started» (только в ответе). */
async function mockOneInProgress(page: Page) {
  await page.route(/\/rest\/v1\/rpc\/list_candidates/, async (route) => {
    const res = await route.fetch();
    const rows = (await res.json()) as Row[];
    const i = rows.findIndex((r) => r.invite);
    if (i >= 0) {
      rows[i] = {
        ...rows[i],
        full_name: FAKE_NAME,
        execution_status: 'simulation_started',
        invite: { ...rows[i].invite, status: 'simulation_started' },
        attempt: null,
        completed_at: null,
        report_status: null,
      };
    }
    await route.fulfill({ response: res, json: rows });
  });
}

test.describe(`Статус simulation_started = «${LABEL}» (${HASH})`, () => {
  test(`/candidates: в фильтре «סטטוס» есть «${LABEL}», нет «${OLD_LABEL}»; колонка «ביצוע» строки simulation_started — «${LABEL}» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await mockOneInProgress(page);
    await page.goto('/candidates');
    await expect(page.getByTestId('pagination-range')).toHaveText(/^מציג \d/, { timeout: 30_000 });

    // Источник: решение пользователя 14.10 (context.md) — фильтр «סטטוס» называет статус «בתהליך».
    const filter = page.locator('select[name="status"]');
    const options = await filter.locator('option').allInnerTexts();
    expect(options.map((o) => o.trim()), 'варианты фильтра «סטטוס»').toContain(LABEL);
    expect(options.join(' | ')).not.toContain(OLD_LABEL);

    // Источник: там же — колонка статуса строки.
    const row = page.getByTestId('candidate-row').filter({ has: page.locator('td[data-label="שם"]').getByText(FAKE_NAME, { exact: true }) });
    await expect(row, 'подменённая строка simulation_started').toHaveCount(1);
    await expect(row).toHaveAttribute('data-invite-status', 'simulation_started');
    await expect(row.locator('td[data-label="ביצוע"]')).toContainText(LABEL);
    await expect(page.locator('main')).not.toContainText(OLD_LABEL);

    // Фильтр «בתהליך» оставляет только строки «בתהליך», подменённая — среди них.
    await filter.selectOption({ label: LABEL });
    await expect(page).toHaveURL(/[?&]status=/);
    await expect(row).toHaveCount(1);
    const cells = await page.getByTestId('candidate-row').locator('td[data-label="ביצוע"]').allInnerTexts();
    expect(cells.length).toBeGreaterThan(0);
    for (const c of cells) expect(c, 'строка в фильтре «בתהליך»').toContain(LABEL);
    await expect(page.locator('main')).not.toContainText(OLD_LABEL);
  });

  test(`дашборд: событие simulation_started в «פעילות אחרונה» — «${LABEL}», нет «${OLD_LABEL}» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const candidateId = '00000000-0000-4000-8000-0000000b9803';
    await page.route(/\/rest\/v1\/rpc\/get_business_dashboard/, async (route) => {
      const res = await route.fetch();
      const body = await res.json();
      body.recent_activity = [
        { at: new Date().toISOString(), axis: 'invitation', status: 'simulation_started', candidate_id: candidateId, candidate_name: FAKE_NAME },
        ...(body.recent_activity ?? []),
      ];
      await route.fulfill({ response: res, json: body });
    });
    await page.goto('/');

    // Источник: решение пользователя 14.10 — лента дашборда пишет «בתהליך».
    const feed = page.getByTestId('dashboard-activity');
    await expect(feed).toBeVisible({ timeout: 30_000 });
    const item = feed.locator(`[data-testid="activity-item"][data-candidate-id="${candidateId}"]`);
    await expect(item).toHaveCount(1);
    await expect(item).toContainText(LABEL);
    await expect(feed).not.toContainText(OLD_LABEL);
    await expect(page.locator('main')).not.toContainText(OLD_LABEL);
  });
});
